import csv,glob,hashlib,json,pathlib
root=pathlib.Path('/root/autodl-tmp/SimAI-handoff');out=pathlib.Path(__file__).parent
prefix=root/'docs/dag_defense/environment/diagnostics/serial-prefix-comparison-20261126/requests.csv';tails=root/'docs/dag_defense/environment/diagnostics/first-last-output-boundary-20261126/paired.csv';rd=pathlib.Path('/root/autodl-tmp/dag-handoff/runs/whole-forward-replay-20261126/dag');simdir=next(rd.glob('2026*'))
a=next(csv.DictReader(prefix.open()));tails_by_id={x['router_id']:x for x in csv.DictReader(tails.open())};b=tails_by_id[a['router_id']]
# Prefix relative times originate from the actual router arrival in the same run.
arrival_ns=int(b['first_step_return_ns'])-round(float(a['first_step_return_ms'])*1e6)
actual=[{'event':'router_arrival','timestamp_ns':arrival_ns,'scope':'server monotonic origin'}]
for k in ('prefill_send_ms','prefill_worker_start_ms','producer_send_start_ms','producer_send_return_ms','prefill_worker_return_ms','prefill_response_ms','decode_send_ms','decode_worker_start_ms','receive_start_ms','receive_return_ms','first_step_return_ms','router_first_ms'):
 actual.append({'event':k.removesuffix('_ms'),'timestamp_ns':arrival_ns+round(float(a[k])*1e6),'scope':'host observation; send/receive return not GPU completion'})
for k in ('last_step_return_ns','final_choice_ns','server_complete_ns'):actual.append({'event':k.removesuffix('_ns'),'timestamp_ns':int(b[k]),'scope':'host observation; server completion is stream end'})
assert [x['timestamp_ns'] for x in actual]==sorted(x['timestamp_ns'] for x in actual)
metrics=list(csv.DictReader((simdir/'request_metrics.csv').open()));assert len(metrics)==1;met=metrics[0];assert float(met['request_num_prefill_tokens'])==512 and float(met['request_num_decode_tokens'])==64
pd=list(csv.DictReader((simdir/'pd-transfers.csv').open()));assert len(pd)==1 and pd[0]['state']=='COMPLETED';timing=list(csv.DictReader((simdir/'timeline.csv').open()));ft=[x for x in timing if x['task_id']=='consumer.first_token'];assert len(ft)==1
sim=[{'event':n,'time_s':float(v)} for n,v in [('arrival',met['arrived_at']),('prefill_end',pd[0]['prefill_completed_at_s']),('transfer_start',pd[0]['transfer_started_at_s']),('kv_ready',pd[0]['kv_ready_at_s']),('consumer_first_token_start',ft[0]['start_at_s']),('consumer_first_token_end',ft[0]['end_at_s']),('first_decode_start',pd[0]['first_decode_start_s']),('last_batch_complete',met['completed_at'])]];assert [x['time_s'] for x in sim]==sorted(x['time_s'] for x in sim)
trace=json.loads((simdir/'chrome_trace.json').read_text())['traceEvents'];dec=[x for x in trace if x.get('pid')==1 and x.get('ph')=='X' and x.get('args',{}).get('request_ids')];assert len(dec)==63
inputs=[prefix,tails,simdir/'request_metrics.csv',simdir/'pd-transfers.csv',simdir/'timeline.csv',simdir/'chrome_trace.json'];r={'real_router_id':a['router_id'],'actual_clock_id':'CLOCK_MONOTONIC','actual':actual,'simulation':sim,'input_tokens':512,'output_tokens':64,'real_consumer_steps':64,'simulation_subsequent_decode_batches':len(dec),'actual_server_e2e_s':(int(b['server_complete_ns'])-arrival_ns)/1e9,'simulation_last_batch_elapsed_s':float(met['completed_at'])-float(met['arrived_at']),'simulation_is_adapted_candidate_not_pristine':True,'source_sha256':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in inputs},'limitations':['distinct observations in real and simulated host clock domains; do not subtract absolute clocks','real worker events do not prove exact GPU KVReady','router streaming completion is not simulator last model batch completion','the same candidate input/profile is a diagnostic, not frozen or formal validation','host receive start and simulated transfer start have different meanings']};(out/'audit.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r,indent=2))
